/// Environment variable controlling", "originalFile": "//! Truncation of min/max statistics for `BYTE_ARRAY` (string / binary) columns.
//!
//! A single very large value in a string or binary column would otherwise be
//! copied verbatim into the column statistics (as both the min and max bound),
//! producing enormous metadata. To bound the metadata size we truncate the
//! statistics to a configurable number of bytes.
//!
//! The truncation length is controlled by the
//! `POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN` environment variable and
//! defaults to [`DEFAULT_TRUNCATE_LEN`] bytes. Setting it to `0` disables
//! truncation entirely.

use std::str;

/// Environment variable controlling the maximum length (in bytes) of the
/// min/max statistics stored for `BYTE_ARRAY` (string / binary) columns.
const TRUNCATE_LEN_ENV: &str = "POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN";

/// Default truncation length in bytes.
const DEFAULT_TRUNCATE_LEN: usize = 64;

/// Returns the configured statistics truncation length.
///
/// - `None` means truncation is disabled (the environment variable is set to
///   `0`).
/// - `Some(n)` means statistics are truncated to at most `n` bytes.
///
/// The environment variable is read on every call (rather than cached) so that
/// it can be changed at runtime.
fn statistics_truncate_length() -> Option<usize> {
    let len = std::env::var(TRUNCATE_LEN_ENV)
        .ok()
        .and_then(|v| v.trim().parse::<usize>().ok())
        .unwrap_or(DEFAULT_TRUNCATE_LEN);
    (len != 0).then_some(len)
}

/// Truncate the `min`/`max` statistics of a `BYTE_ARRAY` column.
///
/// `is_utf8` selects between Unicode-aware truncation (for string columns) and
/// raw byte-level truncation (for binary columns). Values that already fit
/// within the configured limit are returned unchanged.
pub(crate) fn truncate_statistics(
    min: Option<Vec<u8>>,
    max: Option<Vec<u8>>,
    is_utf8: bool,
) -> (Option<Vec<u8>>, Option<Vec<u8>>) {
    match statistics_truncate_length() {
        // Truncation disabled: keep the exact values.
        None => (min, max),
        Some(length) => (
            min.and_then(|v| truncate_min_value(&v, length, is_utf8)),
            max.and_then(|v| truncate_max_value(&v, length, is_utf8)),
        ),
    }
}

/// Truncate a value used as a *minimum* bound to at most `length` bytes.
fn truncate_min_value(value: &[u8], length: usize, is_utf8: bool) -> Option<Vec<u8>> {
    if value.len() <= length {
        return Some(value.to_vec());
    }

    if is_utf8 {
        match str::from_utf8(value) {
            Ok(s) => truncate_utf8(s, length),
            // The column claims to be UTF-8 but the value is not; fall back to
            // raw byte-level truncation.
            Err(_) => Some(value[..length].to_vec()),
        }
    } else {
        Some(value[..length].to_vec())
    }
}

/// Truncate a value used as a *maximum* bound to at most `length` bytes and turn
/// it into a valid upper bound.
///
/// Returns `None` when no valid upper bound can be produced (e.g. every byte is
/// `0xFF`), in which case the maximum statistic should be omitted.
fn truncate_max_value(value: &[u8], length: usize, is_utf8: bool) -> Option<Vec<u8>> {
    if value.len() <= length {
        return Some(value.to_vec());
    }

    if is_utf8 {
        match str::from_utf8(value) {
            Ok(s) => truncate_and_increment_utf8(s, length),
            Err(_) => truncate_and_increment_binary(value, length),
        }
    } else {
        truncate_and_increment_binary(value, length)
    }
}

/// Return the longest valid, non-empty UTF-8 prefix of `data` that fits within
/// `length` bytes, or `None` if no such prefix exists.
fn truncate_utf8(data: &str, length: usize) -> Option<Vec<u8>> {
    let split = (1..=length.min(data.len())).rfind(|x| data.is_char_boundary(*x));
    split.map(|split| data.as_bytes()[..split].to_vec())
}

/// Truncate `data` to the longest valid UTF-8 prefix fitting within `length`
/// bytes and increment its last character to form a valid upper bound.
fn truncate_and_increment_utf8(data: &str, length: usize) -> Option<Vec<u8>> {
    let split = (1..=length.min(data.len())).rfind(|x| data.is_char_boundary(*x))?;
    increment_utf8(&data[..split])
}

/// Increment the last incrementable character of `data`, preserving the encoded
/// byte-length of that character, and drop everything after it.
///
/// Returns `None` if no character can be incremented without growing its
/// encoded byte-length (e.g. the string is empty or every character is the
/// maximum for its byte-width).
fn increment_utf8(data: &str) -> Option<Vec<u8>> {
    for (idx, original_char) in data.char_indices().rev() {
        let original_len = original_char.len_utf8();
        if let Some(next_char) = char::from_u32(original_char as u32 + 1) {
            // Do not allow the incremented character to grow in byte-width, as
            // that would corrupt the truncated layout.
            if next_char.len_utf8() == original_len {
                let mut result = data.as_bytes()[..idx + original_len].to_vec();
                next_char.encode_utf8(&mut result[idx..]);
                return Some(result);
            }
        }
    }
    None
}

/// Truncate a binary value to at most `length` bytes and turn it into a valid
/// upper bound by incrementing the last non-`0xFF` byte within the limit.
///
/// If every byte within the limit is `0xFF`, the search continues beyond the
/// limit for the first non-`0xFF` byte, which is then incremented. Returns
/// `None` if the whole value consists of `0xFF` bytes.
fn truncate_and_increment_binary(value: &[u8], length: usize) -> Option<Vec<u8>> {
    let limit = length.min(value.len());

    // Common case: there is an incrementable byte within the limit.
    if let Some(i) = value[..limit].iter().rposition(|&b| b != 0xFF) {
        let mut result = value[..=i].to_vec();
        result[i] += 1;
        return Some(result);
    }

    // Every byte within the limit is `0xFF`; search beyond the limit for the
    // first byte that can be incremented.
    if let Some(j) = value.iter().position(|&b| b != 0xFF) {
        let mut result = value[..=j].to_vec();
        result[j] += 1;
        return Some(result);
    }

    None
}
