mod tests {
    use super::*;

    #[test]
    fn utf8_min_ascii() {
        let value = vec![b'A'; 100];
        assert_eq!(truncate_min_value(&value, 64, true), Some(vec![b'A'; 64]));
    }

    #[test]
    fn utf8_min_respects_char_boundary() {
        // 63 'A' followed by a 2-byte character (U+00E9). Truncating to 64 bytes
        // must drop the 2-byte character rather than split it.
        let mut value = vec![b'A'; 63];
        value.extend_from_slice("é".as_bytes());
        assert_eq!(truncate_min_value(&value, 64, true), Some(vec![b'A'; 63]));
    }

    #[test]
    fn utf8_max_ascii() {
        let value = vec![b'A'; 100];
        let mut expected = vec![b'A'; 63];
        expected.push(b'B');
        assert_eq!(truncate_max_value(&value, 64, true), Some(expected));
    }

    #[test]
    fn utf8_max_increment_preserves_width() {
        // 40 copies of U+00E9 (2 bytes each). Truncate to 64 bytes -> 32 copies,
        // then increment the last to U+00EA -> 31 copies + U+00EA.
        let value = "é".repeat(40).into_bytes();
        let mut expected = "é".repeat(31).into_bytes();
        expected.extend_from_slice("ê".as_bytes());
        assert_eq!(truncate_max_value(&value, 64, true), Some(expected));
    }

    #[test]
    fn binary_min_byte_truncation() {
        let value = vec![0x41u8; 100];
        assert_eq!(truncate_min_value(&value, 64, false), Some(vec![0x41; 64]));
    }

    #[test]
    fn binary_max_search_beyond_limit() {
        // Eight 0xFF, one 0x00, six 0xFF; truncate to 1 byte.
        let mut value = vec![0xFFu8; 8];
        value.push(0x00);
        value.extend_from_slice(&[0xFF; 6]);
        let mut expected = vec![0xFFu8; 8];
        expected.push(0x01);
        assert_eq!(truncate_max_value(&value, 1, false), Some(expected));
    }

    #[test]
    fn short_values_unchanged() {
        let value = b"hello".to_vec();
        assert_eq!(truncate_min_value(&value, 64, true), Some(value.clone()));
